//! Parity and regression tests for the MOSS-TTS-Nano TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_moss_tts_nano/`, generated by
//! `tools/gen_moss_tts_nano_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference module (a deterministic
//! character-level tokenizer stands in for sentencepiece, a seeded tiny
//! mono MOSS audio tokenizer for the codec), so the traces carry the
//! composed prompt rows from `build_inference_input_ids`, the greedy
//! `generate_audio_token_ids` frames, the reference codec decode, and
//! the family sampler chain on fixed logits.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::sampling as family_sampling;
use super::{
    build_assistant_prompt_prefix, build_prompt_token_ids, build_user_prompt_after_reference,
    build_user_prompt_prefix, frames_to_codes, lightweight_normalize_text, GenerateParams, Model,
    ModelConfig, PromptMode, StopReason, TemplateIds, DEFAULT_AUDIO_TOKENIZER_REPO,
};
use crate::codec::moss_audio_tokenizer::MossAudioTokenizer;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_moss_tts_nano")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered sampler scores use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum difference against the fixture waveform when the
/// gate was frozen; the assertion uses this value, not a re-measured
/// one. The MOSS codec decode parity measured 6.9e-7 (conv accumulation
/// order), so the gate sits well above the measurement.
const WAVEFORM_TOLERANCE: f32 = 2e-6;

fn model() -> Model {
    Model::open(&testdata("generate")).expect("family model loads")
}

fn stop_model() -> Model {
    Model::open(&testdata("generate_stop")).expect("stop model loads")
}

fn audio_tokenizer() -> MossAudioTokenizer {
    MossAudioTokenizer::open(&testdata("decode")).expect("tiny moss codec loads")
}

fn template(traces: &Value) -> TemplateIds<'_> {
    let pieces = &traces["pieces"];
    let get = |name: &str| -> Vec<i32> { i32_vec(&pieces[name]) };
    // The helper wants slices; leak the small fixture vectors for the
    // test lifetime.
    let user_role_prefix: &'static [i32] = Box::leak(get("user_role_prefix").into_boxed_slice());
    let reference_prefix: &'static [i32] =
        Box::leak(get("user_template_reference_prefix").into_boxed_slice());
    let after_reference: &'static [i32] =
        Box::leak(get("user_template_after_reference").into_boxed_slice());
    let suffix: &'static [i32] = Box::leak(get("user_template_suffix").into_boxed_slice());
    let turn_prefix: &'static [i32] = Box::leak(get("assistant_turn_prefix").into_boxed_slice());
    let role_prefix: &'static [i32] = Box::leak(get("assistant_role_prefix").into_boxed_slice());
    let none_reference: &'static [i32] = Box::leak(get("none_reference").into_boxed_slice());
    TemplateIds {
        user_role_prefix,
        user_template_reference_prefix: reference_prefix,
        user_template_after_reference: after_reference,
        user_template_suffix: suffix,
        assistant_turn_prefix: turn_prefix,
        assistant_role_prefix: role_prefix,
        none_reference,
    }
}

#[test]
fn prompt_rows_match_the_reference_cases() {
    let traces = read_json(&testdata("prompt/traces.json"));
    let ids = template(&traces);
    let model = model();
    let text_ids = i32_vec(&traces["text_ids"]);
    let ref_text_ids = i32_vec(&traces["ref_text_ids"]);
    let codec_traces = read_json(&testdata("decode/traces.json"));
    let codes = i32_rows(&codec_traces["encode_codes"]);
    for case in traces["cases"].as_array().expect("cases") {
        let got = match case["name"].as_str().expect("name") {
            "voice_clone" => model
                .build_inference_input_ids(
                    PromptMode::VoiceClone,
                    &ids,
                    &text_ids,
                    None,
                    Some(&codes),
                )
                .expect("voice clone rows"),
            "continuation_text_only" => model
                .build_inference_input_ids(PromptMode::Continuation, &ids, &text_ids, None, None)
                .expect("continuation rows"),
            "continuation_with_reference" => model
                .build_inference_input_ids(
                    PromptMode::Continuation,
                    &ids,
                    &text_ids,
                    Some(&ref_text_ids),
                    Some(&codes),
                )
                .expect("continuation rows"),
            other => panic!("unknown prompt case {other}"),
        };
        assert_eq!(got, i32_rows(&case["rows"]), "case {}", case["name"]);
    }
}

#[test]
fn greedy_generation_matches_the_reference_frames_and_waveform() {
    let traces = read_json(&testdata("generate/traces.json"));
    let prompt_rows = i32_rows(&traces["prompt_rows"]);
    let mut model = model();
    let params = GenerateParams {
        max_new_frames: traces["max_new_frames"].as_u64().expect("frames") as usize,
        do_sample: false,
        ..GenerateParams::default()
    };
    let (frames, stopped_by) = model
        .generate_audio_token_ids(&prompt_rows, &params, 0)
        .expect("generate runs");
    assert_eq!(frames, i32_rows(&traces["frames"]), "generated frames");
    assert_eq!(stopped_by, StopReason::MaxFrames);
    // The full path decodes through the tiny MOSS codec.
    let tokenizer = audio_tokenizer();
    let got = model
        .generate(&tokenizer, &prompt_rows, &params, 0)
        .expect("generate with decode runs");
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(got.samples.len(), want_wave.len());
    let diff = max_abs_diff(&got.samples, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
    assert_eq!(got.codes, frames_to_codes(&got.frames, model.config.n_vq));
}

#[test]
fn engineered_stop_ends_with_no_frames() {
    let traces = read_json(&testdata("generate_stop/traces.json"));
    let prompt_rows = i32_rows(&traces["prompt_rows"]);
    let mut model = stop_model();
    let params = GenerateParams {
        max_new_frames: traces["max_new_frames"].as_u64().expect("frames") as usize,
        do_sample: false,
        ..GenerateParams::default()
    };
    let tokenizer = audio_tokenizer();
    let got = model
        .generate(&tokenizer, &prompt_rows, &params, 0)
        .expect("generate runs");
    assert!(got.frames.is_empty(), "no frames survive the stop");
    assert_eq!(got.codes, Vec::<Vec<i32>>::new());
    assert!(got.samples.is_empty());
    assert_eq!(got.stopped_by, StopReason::EndOfText);
}

#[test]
fn family_sampler_matches_the_reference_on_fixed_logits() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let logits = f32_vec(&case["logits"]);
        if let Some(penalized) = case["penalized"].as_array() {
            let mut scores = logits.clone();
            family_sampling::apply_repetition_penalty(
                &mut scores,
                &i32_vec(&case["context"]),
                case["repetition_penalty"].as_f64().expect("penalty") as f32,
            );
            let diff = max_abs_diff(&scores, &f32_vec(&Value::Array(penalized.clone())));
            assert!(diff <= 2e-6, "case {} penalty diff {diff}", case["name"]);
        }
        if let Some(top_k) = case["top_k_scores"].as_array() {
            let scaled: Vec<f32> = logits
                .iter()
                .map(|&x| x / case["temperature"].as_f64().unwrap() as f32)
                .collect();
            let filtered = family_sampling::apply_top_k(
                &scaled,
                Some(case["top_k"].as_u64().expect("top_k") as usize),
            )
            .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_k.clone())));
            assert!(diff <= 2e-6, "case {} top_k diff {diff}", case["name"]);
        }
        if let Some(top_p) = case["top_p_scores"].as_array() {
            let scaled: Vec<f32> = logits
                .iter()
                .map(|&x| x / case["temperature"].as_f64().unwrap() as f32)
                .collect();
            // The chained case applies top-p on top of the recorded
            // top-k output; a standalone case applies it on the scores.
            let base = if case["top_k_scores"].is_null() {
                scaled
            } else {
                family_sampling::apply_top_k(
                    &scaled,
                    Some(case["top_k"].as_u64().expect("top_k") as usize),
                )
                .unwrap()
            };
            let filtered =
                family_sampling::apply_top_p(&base, Some(case["top_p"].as_f64().unwrap() as f32))
                    .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_p.clone())));
            assert!(diff <= 2e-6, "case {} top_p diff {diff}", case["name"]);
        }
        assert_eq!(
            crate::tts::sampling::argmax(&logits),
            case["argmax"].as_u64().expect("argmax") as usize,
            "case {}",
            case["name"]
        );
        if let Some(picked) = case["picked"].as_u64() {
            // The reference returns the candidate TOKEN id; the Rust
            // helper returns the candidate index.
            let got = family_sampling::sample_assistant_text_token(
                &logits,
                9,
                7,
                false,
                1.0,
                Some(50),
                Some(1.0),
                crate::music::minimax_music3::rng::Key::new(1),
            )
            .expect("candidate choice");
            assert_eq!([9, 7][got], picked as i32, "case {}", case["name"]);
        }
    }
}

#[test]
fn prompt_piece_helpers_compose_like_the_reference_builders() {
    // Pure id-composition checks on synthetic pieces.
    let prefix = build_user_prompt_prefix(4, &[20, 21], &[22, 23]);
    assert_eq!(prefix, vec![4, 20, 21, 22, 23]);
    assert_eq!(build_user_prompt_after_reference(&[30, 31]), vec![30, 31]);
    let assistant = build_assistant_prompt_prefix(&[40], 5, &[41], 4, &[42, 43]);
    assert_eq!(assistant, vec![40, 5, 41, 4, 42, 43]);
    let prompt = build_prompt_token_ids(&[1, 2], &[3], &[4], &[5, 6], &[7]);
    assert_eq!(prompt, vec![1, 2, 3, 4, 5, 6, 7]);
}

#[test]
fn lightweight_normalization_collapses_whitespace() {
    assert_eq!(lightweight_normalize_text("  a \t b \n c "), "a b c");
    assert_eq!(lightweight_normalize_text(""), "");
}

#[test]
fn config_defaults_match_the_reference_dataclasses() {
    let config = ModelConfig::from_json(&serde_json::json!({})).expect("defaults parse");
    assert_eq!(config.n_vq, 16);
    assert_eq!(config.audio_vocab_size, 1024);
    assert_eq!(config.audio_codebook_sizes, vec![1024; 16]);
    assert_eq!(config.audio_pad_token_id, 1024);
    assert_eq!(config.pad_token_id, 3);
    assert_eq!(config.im_start_token_id, 4);
    assert_eq!(config.im_end_token_id, 5);
    assert_eq!(config.audio_start_token_id, 6);
    assert_eq!(config.audio_end_token_id, 7);
    assert_eq!(config.audio_user_slot_token_id, 8);
    assert_eq!(config.audio_assistant_slot_token_id, 9);
    assert_eq!(config.audio_tokenizer_sample_rate, 48000);
    assert_eq!(config.local_transformer_layers, 1);
    assert_eq!(config.gpt2_config.vocab_size, 16384);
    assert_eq!(config.gpt2_config.n_embd, 768);
    assert_eq!(config.gpt2_config.n_inner, 3072);
    assert_eq!(config.gpt2_config.n_layer, 12);
    assert_eq!(config.gpt2_config.n_head, 12);
    assert_eq!(config.gpt2_config.activation_function, "gelu_new");
    assert_eq!(config.gpt2_config.position_embedding_type, "rope");
    // local_gpt2_config derives the local depth and context width.
    let local = config.local_gpt2_config();
    assert_eq!(local.n_layer, 1);
    assert_eq!(local.n_positions, 17);
    assert_eq!(local.n_embd, 768);
    // HF alias fields feed the gpt2 names.
    let aliased = ModelConfig::from_json(&serde_json::json!({
        "gpt2_config": {
            "hidden_size": 32,
            "num_hidden_layers": 2,
            "num_attention_heads": 4,
            "intermediate_size": 64,
        },
        "n_vq": 2,
        "audio_codebook_sizes": [8, 4],
    }))
    .expect("aliased config parses");
    assert_eq!(aliased.gpt2_config.n_embd, 32);
    assert_eq!(aliased.gpt2_config.n_layer, 2);
    assert_eq!(aliased.gpt2_config.n_head, 4);
    assert_eq!(aliased.gpt2_config.n_inner, 64);
    assert_eq!(aliased.audio_codebook_sizes, vec![8, 4]);
    // A codebook size list must match n_vq.
    assert!(ModelConfig::from_json(&serde_json::json!({
        "n_vq": 3,
        "audio_codebook_sizes": [8, 8],
    }))
    .is_err());
    // Learned positions are refused (no shipped checkpoint uses them).
    let absolute = ModelConfig::from_json(&serde_json::json!({
        "gpt2_config": {"position_embedding_type": "absolute"},
    }));
    assert!(absolute.is_err());
    assert_eq!(
        DEFAULT_AUDIO_TOKENIZER_REPO,
        "mlx-community/MOSS-Audio-Tokenizer-Nano"
    );
}

#[test]
fn config_refuses_zero_heads_and_zero_channels() {
    // n_head = 0 used to panic on `n_embd % n_head` at the first stack load.
    assert!(ModelConfig::from_json(&serde_json::json!({
        "gpt2_config": {"n_head": 0},
    }))
    .is_err());
    // n_head must divide n_embd (the head_dim division depends on it).
    assert!(ModelConfig::from_json(&serde_json::json!({
        "gpt2_config": {"n_embd": 30, "n_head": 4},
    }))
    .is_err());
    // Zero VQ channels leaves no audio tables and a degenerate frame width.
    assert!(ModelConfig::from_json(&serde_json::json!({"n_vq": 0})).is_err());
}

#[test]
fn resolve_nq_and_prompt_widths_are_validated() {
    let mut model = model();
    assert_eq!(model.resolve_nq(None).unwrap(), 4);
    assert_eq!(model.resolve_nq(Some(2)).unwrap(), 2);
    assert!(model.resolve_nq(Some(0)).is_err());
    assert!(model.resolve_nq(Some(5)).is_err());
    let error = model
        .generate_audio_token_ids(
            &[vec![1, 2, 3]],
            &GenerateParams {
                do_sample: false,
                ..GenerateParams::default()
            },
            0,
        )
        .unwrap_err();
    assert!(error.to_string().contains("wide"), "{error}");
    let error = model
        .generate_audio_token_ids(&[], &GenerateParams::default(), 0)
        .unwrap_err();
    assert!(error.to_string().contains("empty prompt"), "{error}");
    // Out-of-range audio codes in the prompt are refused where the
    // reference embedding lookup would raise.
    let traces = read_json(&testdata("generate/traces.json"));
    let mut bad = i32_rows(&traces["prompt_rows"]);
    bad[0][1] = 99;
    let error = model
        .generate_audio_token_ids(
            &bad,
            &GenerateParams {
                do_sample: false,
                ..GenerateParams::default()
            },
            0,
        )
        .unwrap_err();
    assert!(error.to_string().contains("outside codebook"), "{error}");
}

#[test]
fn the_cacheless_replay_path_matches_the_cached_path() {
    let traces = read_json(&testdata("generate/traces.json"));
    let prompt_rows = i32_rows(&traces["prompt_rows"]);
    let cached = {
        let mut model = model();
        let params = GenerateParams {
            max_new_frames: 3,
            do_sample: false,
            ..GenerateParams::default()
        };
        model
            .generate_audio_token_ids(&prompt_rows, &params, 0)
            .expect("cached run")
    };
    let replayed = {
        let mut model = model();
        let params = GenerateParams {
            max_new_frames: 3,
            do_sample: false,
            use_kv_cache: false,
            ..GenerateParams::default()
        };
        model
            .generate_audio_token_ids(&prompt_rows, &params, 0)
            .expect("cacheless run")
    };
    assert_eq!(cached, replayed);
}
